1	import { notFound } from "next/navigation";
2	import { PORTFOLIO_DETAILS } from "@/lib/constants/portfolio-details";
3	import { createMetadata } from "@/lib/seo/metadata";
4	import { JsonLd, breadcrumbSchema } from "@/lib/seo/jsonld";
5	import { SITE_CONFIG } from "@/lib/constants/site";
6	import { CaseStudyContent } from "@/components/our-works-detail/case-study-content";
7	import { CaseStudyGallery } from "@/components/our-works-detail/case-study-gallery";
8	import layoutStyles from "./case-study-layout.module.css";
9	
10	export function generateStaticParams() {
11	  return PORTFOLIO_DETAILS.map((d) => ({ slug: d.slug }));
12	}
13	
14	export async function generateMetadata({
15	  params,
16	}: {
17	  params: Promise<{ slug: string }>;
18	}) {
19	  const { slug } = await params;
20	  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
21	  if (!detail) return {};
22	  const truncated =
23	    detail.challenge.length > 155
24	      ? `${detail.challenge.slice(0, 152)}...`
25	      : detail.challenge;
26	  return createMetadata({
27	    title: `${detail.title} | Case Study | Boldteq`,
28	    description: truncated,
29	    path: `/our-works/${detail.slug}`,
30	    ogImage: detail.gallery[0],
31	    type: "article",
32	  });
33	}
34	
35	export default async function CaseStudyPage({
36	  params,
37	}: {
38	  params: Promise<{ slug: string }>;
39	}) {
40	  const { slug } = await params;
41	  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
42	  if (!detail) notFound();
43	
44	  const breadcrumbs = breadcrumbSchema([
45	    { name: "Our Works", path: "/our-works" },
46	    { name: detail.title, path: `/our-works/${detail.slug}` },
47	  ]);
48	
49	  const PUBLISHED = "2026-04-12T00:00:00Z";
50	  const articleSchema = {
51	    "@context": "https://schema.org",
52	    "@type": "Article",
53	    headline: detail.title,
54	    description: detail.challenge,
55	    image: detail.gallery.map((url) => ({
56	      "@type": "ImageObject",
57	      url,
58	    })),
59	    datePublished: PUBLISHED,
60	    dateModified: PUBLISHED,
61	    author: {
62	      "@type": "Organization",
63	      name: SITE_CONFIG.name,
64	      url: SITE_CONFIG.url,
65	    },
66	    publisher: {
67	      "@type": "Organization",
68	      name: SITE_CONFIG.name,
69	      logo: {
70	        "@type": "ImageObject",
71	        url: "https://cdn.prod.website-files.com/68ee3857579ec95674c7dd80/6937cbaf47872f6a8eb16f1c_Group%2046895.svg",
72	      },
73	    },
74	    mainEntityOfPage: {
75	      "@type": "WebPage",
76	      "@id": `${SITE_CONFIG.url}/our-works/${detail.slug}`,
77	    },
78	    about: {
79	      "@type": "CreativeWork",
80	      name: detail.title,
81	      keywords: detail.platform,
82	    },
83	  };
84	
85	  return (
86	    <section className={layoutStyles.pageOut}>
87	      <JsonLd data={breadcrumbs} id="schema-breadcrumbs" />
88	      <JsonLd data={articleSchema} id="schema-case-study" />
89	      <div className={layoutStyles.container}>
90	        <div className={layoutStyles.grid}>
91	          <CaseStudyContent detail={detail} />
92	          <CaseStudyGallery images={detail.gallery} title={detail.title} />
93	        </div>
94	      </div>
95	    </section>
96	  );
97	}
