3	import Image from "next/image";
4	import type { PortfolioItem } from "@/types/portfolio";
5	import styles from "./portfolio-card.module.css";
6	
7	const CATEGORY_LABELS: Record<string, string> = {
8	  shopify: "Shopify",
9	  wordpress: "WordPress",
10	};
11	
12	interface PortfolioCardProps {
13	  item: PortfolioItem;
14	  onCardClick: (item: PortfolioItem) => void;
15	  eager?: boolean;
16	}
17	
18	export function PortfolioCard({ item, onCardClick, eager = false }: PortfolioCardProps) {
19	  return (
20	    <article
21	      className={styles.card}
22	      onClick={() => onCardClick(item)}
23	      role="button"
24	      tabIndex={0}
25	      onKeyDown={(e) => {
26	        if (e.key === "Enter" || e.key === " ") {
27	          e.preventDefault();
28	          onCardClick(item);
29	        }
30	      }}
31	      aria-label={`View ${item.name} project`}
32	    >
33	      <div className={styles.imageWrapper}>
34	        {/* Category badge — top left */}
35	        <span className={styles.categoryBadge}>
36	          {CATEGORY_LABELS[item.category] ?? item.category}
37	        </span>
38	
39	        {/* Card image — fill mode, unoptimized=false to enable priority preloading */}
40	        <Image
41	          src={item.featuredImage}
42	          alt={`${item.name} — Boldteq portfolio project`}
43	          fill
44	          sizes="(max-width: 767px) 90vw, (max-width: 991px) 45vw, 480px"
45	          className={styles.image}
46	          loading={eager ? "eager" : "lazy"}
47	          priority={eager}
48	          unoptimized={false}
49	        />
50	
51	        {/* Eye icon — bottom right (decorative overlay) */}
52	        <Image
53	          src="/images/webflow/Vector-25.svg"
54	          alt=""
55	          aria-hidden="true"
56	          width={33}
57	          height={33}
58	          className={styles.eyeIcon}
59	        />
60	      </div>
61	    </article>
62	  );
63	}
