13	/** Trap focus within the modal container */
14	function useFocusTrap(containerRef: React.RefObject<HTMLDivElement | null>) {
15	  useEffect(() => {
16	    const container = containerRef.current;
17	    if (!container) return;
18	
19	    const focusableSelectors =
20	      'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])';
21	    const focusableElements = Array.from(
22	      container.querySelectorAll<HTMLElement>(focusableSelectors)
23	    );
24	    const firstFocusable = focusableElements[0];
25	    const lastFocusable = focusableElements[focusableElements.length - 1];
26	
27	    // Move focus into modal on open
28	    firstFocusable?.focus();
29	
30	    function handleKeyDown(e: KeyboardEvent) {
31	      if (e.key !== "Tab") return;
32	      if (focusableElements.length === 0) {
33	        e.preventDefault();
34	        return;
35	      }
36	      if (e.shiftKey) {
37	        if (document.activeElement === firstFocusable) {
38	          e.preventDefault();
39	          lastFocusable?.focus();
40	        }
41	      } else {
42	        if (document.activeElement === lastFocusable) {
43	          e.preventDefault();
44	          firstFocusable?.focus();
45	        }
46	      }
47	    }
48	
49	    container.addEventListener("keydown", handleKeyDown);
50	    return () => container.removeEventListener("keydown", handleKeyDown);
51	  }, [containerRef]);
52	}
53	
54	export function PortfolioPopup({ item, onClose }: PortfolioPopupProps) {
55	  const containerRef = useRef<HTMLDivElement>(null);
56	  const titleId = `popup-title-${item.slug}`;
57	
58	  useFocusTrap(containerRef);
59	
60	  const handleKeyDown = useCallback(
61	    (e: KeyboardEvent) => {
62	      if (e.key === "Escape") onClose();
63	    },
64	    [onClose]
65	  );
66	
67	  useEffect(() => {
68	    document.addEventListener("keydown", handleKeyDown);
69	    document.body.style.overflow = "hidden";
70	
71	    return () => {
72	      document.removeEventListener("keydown", handleKeyDown);
73	      document.body.style.overflow = "";
74	    };
75	  }, [handleKeyDown]);
76	
77	  // Full content mode for items with detail pages, gallery/image mode for others
78	  const isFullMode = item.hasDetailPage;
79	  const containerClass = isFullMode
80	    ? styles.container
81	    : `${styles.container} ${styles.containerGallery}`;
82	
83	  return (
84	    <div
85	      className={styles.overlay}
86	      onClick={(e) => {
87	        if (e.target === e.currentTarget) onClose();
88	      }}
89	      role="dialog"
90	      aria-modal="true"
91	      aria-labelledby={titleId}
92	    >
93	      <div ref={containerRef} className={containerClass}>
94	        <button
95	          type="button"
96	          className={styles.closeBtn}
97	          onClick={onClose}
98	          aria-label="Close popup"
99	        >
100	          &times;
101	        </button>
102	
103	        {isFullMode ? (
104	          <>
105	            <h2 id={titleId} className="sr-only">
106	              {item.name} project details
107	            </h2>
108	            <iframe
109	              src={`/our-works/${item.slug}`}
110	              className={styles.iframe}
111	              title={`${item.name} project details`}
112	              allowFullScreen
113	            />
114	          </>
115	        ) : (
116	          <div className={styles.galleryContent}>
117	            <div className={styles.galleryImageWrap}>
118	              <Image
119	                src={item.featuredImage}
120	                alt={`${item.name} — Boldteq portfolio project`}
121	                fill
122	                sizes="(max-width: 600px) 90vw, 560px"
123	                className={styles.galleryImage}
124	                priority
125	              />
126	            </div>
127	            <div className={styles.galleryInfo}>
128	              <h2 id={titleId} className={styles.galleryTitle}>
129	                {item.name}
130	              </h2>
131	              <span className={styles.galleryBadge}>{item.category}</span>
132	            </div>
133	          </div>
134	        )}
